/* ─────────────────────────────────────────────────────────────────────────────
   MARI TO THE MOON — a WallStreetBets trading-terminal theme for Marinara Engine
   by kolache · free to reuse

   THE STRUCTURAL IDEA: the app is a trading terminal and every message is an
   order ticket. Chats are positions on a watchlist, replies are trade
   confirmations with a side stripe and a P&L tag, the message box is the
   order-entry pad, the top bar carries a live ticker tape, Home is a wall of
   terminal panels, Library pages are ledger sheets on chart paper, and dialogs
   are confirmation slips with a tear-off edge.

   Shape spec
   - containers 3px · fields 3px · buttons 3px · tags/chips 2px · avatars 3px
     (square "ticker chips", never round)
   - border: 1px solid var(--ov-line) everywhere; tickets add a 4px side stripe
     on the left (character = green "long", you = gold "order")
   - shadow: NONE. Depth comes from rules and stripes only, like a terminal.
   - selected: inset 3px left bar in the accent + 10% fill (never an outset ring)
   - focus: inset 0 0 0 2px accent ring (follows the 3px radius)
   - tear-off edge: a dotted perforation along the foot of tickets and slips
   ───────────────────────────────────────────────────────────────────────────── */

:root {
  --mari-tokens-version: 1;

  /* palette constants (both schemes read these) */
  --tt-green: #1f9d5a;
  --tt-red: #d9434f;
  --tt-gold: #c98a12;
  --tt-ink: #0d1813;

  --radius: 3px;
  --tt-r: 3px;
  --tt-code: color-mix(in srgb, var(--foreground) 55%, transparent);
  --tt-chip-r: 2px;

  --mari-font-ui: "Moon Sans", "Inter", system-ui, sans-serif;
  --mari-font-heading: "Moon Mono", "JetBrains Mono", ui-monospace, monospace;
  --mari-font-chat: "Moon Sans", "Inter", system-ui, sans-serif;
  --tt-mono: "Moon Mono", "JetBrains Mono", ui-monospace, monospace;

  /* long replies */
  --mari-chat-font-size: 15.5px;
  --mari-chat-line-height: 1.62;
  --mari-message-measure: 70ch;
  --mari-chat-column: 56rem;
  --mari-dialogue-weight: 500;
  --mari-paragraph-gap: 0.8em;
  --mari-text-outline: 0;
  --mari-msg-head-rule: 1px dashed var(--ov-line);
  --mari-pinned-speaker: on;
  --mari-min-ui-text: 11px;

  --mari-selected-tint: var(--primary);
  --mari-composer-placeholder: "Place your order...";
  --mari-chat-row-art-opacity: 0;
  --mari-home-art: none;
  --mari-home-widget-radius: 3px;
  --mari-home-widget-border-width: 1px;
  --mari-home-widget-glow: transparent;
  --mari-home-widget-title-font: var(--tt-mono);
  --mari-home-widget-eyebrow-size: 0.66rem;
  --mari-home-widget-text-size: 0.84rem;
  --mari-top-bar-plate-radius: 3px;
  --mari-phone-avatar: hidden;
  --mari-mini-avatar-size: 22px;
  --mari-card-art-placeholder:
    repeating-linear-gradient(90deg, transparent 0 15px, color-mix(in srgb, var(--primary) 14%, transparent) 15px 16px),
    repeating-linear-gradient(0deg, transparent 0 15px, color-mix(in srgb, var(--primary) 14%, transparent) 15px 16px),
    linear-gradient(160deg, color-mix(in srgb, var(--primary) 18%, var(--card)), var(--card));

  --mari-app-backdrop-position: center bottom;

  /* status + gauges follow the market */
  --mari-status-online: #2bd67b;
  --mari-status-idle: #f2b84b;
  --mari-status-dnd: #ff5c6c;
  --mari-gauge-ok: #2bd67b;
  --mari-gauge-warn: #f2b84b;
  --mari-gauge-danger: #ff4d5e;
  --mari-lore-constant: #2bd67b;
  --mari-lore-selective: #f2b84b;
  --mari-lore-normal: #6aa7ff;

  /* ── weather: market weather ──
     rain falls as green ticks, a storm is a crash (red bolts down the
     edges, the backdrop's screens go red), snow is money falling (coins and
     diamonds), wind blows banknotes, blossom launches little rockets, fog is
     FUD. The backdrops paint their own sun and moon. */
  --mari-weather-moon: none;
  --mari-weather-sun: none;
  --mari-weather-snow-image: url("theme:wx-coin-a.webp") url("theme:wx-coin-b.webp") url("theme:wx-diamond.webp");
  --mari-weather-snow-size: 0.9;
  --mari-weather-hail-image: url("theme:wx-diamond.webp");
  --mari-weather-leaf-image: url("theme:wx-note-a.webp") url("theme:wx-note-b.webp");
  --mari-weather-leaf-size: 1;
  --mari-weather-petal-image: url("theme:wx-rocket.webp");
  --mari-weather-petal-size: 0.9;
  --mari-weather-rain-length: 1.6;
  --mari-weather-dust-shape: square;
  --mari-weather-star-shape: square;
  --mari-weather-lightning-bolt: 2;
  --mari-weather-amount: 0.8;
  --mari-weather-strength: 1.3;
  --mari-weather-tint-strength: 0.55;
}

/* ═══════════════════════ NIGHT: after-hours terminal ═══════════════════════ */
:root[data-theme="dark"] {
  --background: #07100c;
  --foreground: #dcefe4;
  --card: color-mix(in srgb, #0b1712 92%, transparent);
  --card-foreground: #dcefe4;
  --popover: #0c1813;
  --popover-foreground: #dcefe4;
  --primary: #2bd67b;
  --primary-foreground: #03150b;
  --secondary: #12241b;
  --secondary-foreground: #dcefe4;
  --muted: #11201a;
  --muted-foreground: #93b5a2;
  --accent: #173226;
  --accent-foreground: #e8fff1;
  --destructive: #ff4d5e;
  --destructive-foreground: #1a0306;
  --border: #22402f;
  --input: #22402f;
  --ring: #2bd67b;
  --sidebar: color-mix(in srgb, #08120e 96%, transparent);
  --sidebar-foreground: #d4eadc;
  --sidebar-border: #1d3829;
  --sidebar-accent: #12261c;
  --sidebar-accent-foreground: #e8fff1;

  --ov-line: #22402f;
  --ov-text: #dcefe4;
  --ov-muted: #9cbcaa;
  --ov-dim: #6f907e;
  --ov-hover: color-mix(in srgb, #2bd67b 9%, transparent);
  --ov-active-bg: color-mix(in srgb, #2bd67b 16%, transparent);
  --mari-accent-text: #4fe597;
  --mari-chrome-accent: #2bd67b;
  --tt-gold: #f2b84b;
  --tt-gold-ink: #1a1203;
  --tt-red: #ff5c6c;
  --tt-green: #2bd67b;
  --tt-tape: url("theme:tape-dark.webp");
  --tt-paper: #0a1611;
  --tt-grid: color-mix(in srgb, #2bd67b 7%, transparent);
  --tt-ticket: color-mix(in srgb, #0b1712 93%, transparent);
  --tt-ticket-user: color-mix(in srgb, #15180c 93%, transparent);
  --tt-head-bg: #050b08;
  --tt-head-fg: #f2b84b;

  --mari-dialogue-color: #ffd27a;
  --mari-message-time: #8db39d;
  --mari-mode-conversation: #6aa7ff;
  --mari-mode-roleplay: #2bd67b;
  --mari-mode-game: #f2b84b;
  --ov-mode-conversation: #6aa7ff;
  --ov-mode-roleplay: #2bd67b;
  --ov-mode-game: #f2b84b;
  --mari-home-pink: #ff5c6c;
  --mari-home-violet: #b48cff;

  --mari-app-backdrop: url("theme:floor-night.webp");
  --mari-home-wash: color-mix(in srgb, #050b08 45%, transparent);
  --mari-chat-wash:
    repeating-linear-gradient(90deg, transparent 0 47px, color-mix(in srgb, #2bd67b 6%, transparent) 47px 48px),
    repeating-linear-gradient(0deg, transparent 0 47px, color-mix(in srgb, #2bd67b 6%, transparent) 47px 48px),
    color-mix(in srgb, #050b08 62%, transparent);
  --mari-page-floor: color-mix(in srgb, #07100c 95%, transparent);
  --mari-scrim: color-mix(in srgb, #020604 72%, transparent);
  --mari-confirm-scrim: color-mix(in srgb, #020604 40%, transparent);
  --mari-top-bar-plate: color-mix(in srgb, #08120e 92%, transparent);
  --mari-top-bar-plate-active: color-mix(in srgb, #2bd67b 26%, #08120e);
  --mari-home-widget-bg: color-mix(in srgb, #08120e 88%, transparent);
  --mari-home-widget-border: #22402f;
  --mari-home-widget-title-color: #e8fff1;
  --mari-home-widget-muted: #9cbcaa;
  --mari-stage-empty-bg: linear-gradient(180deg, #08120e, #050b08);
  --mari-user-avatar-placeholder: linear-gradient(135deg, #f2b84b, #a8641f);

  --mari-weather-rain-color: #6ff0a8;
  --mari-weather-snow-color: #f2d27a;
  --mari-weather-fog-color: #5b7a6a;
  --mari-weather-dust-color: #2bd67b;
  --mari-weather-star-color: #f3eedb;
  --mari-weather-lightning-color: #ff5c6c;
}

/* ═══════════════════════ DAY: pre-market trading floor ═══════════════════════ */
:root[data-theme="light"] {
  --background: #f3f1e7;
  --foreground: #14211a;
  --card: color-mix(in srgb, #fffef8 93%, transparent);
  --card-foreground: #14211a;
  --popover: #fffef8;
  --popover-foreground: #14211a;
  --primary: #0b7f45;
  --primary-foreground: #ffffff;
  --secondary: #e7eadf;
  --secondary-foreground: #14211a;
  --muted: #eceee4;
  --muted-foreground: #4a5d53;
  --accent: #dcefe2;
  --accent-foreground: #0b3d24;
  --destructive: #c42b3b;
  --destructive-foreground: #ffffff;
  --border: #b1bdac;
  --input: #a9b6a4;
  --ring: #0b7f45;
  --sidebar: color-mix(in srgb, #fbfaf3 96%, transparent);
  --sidebar-foreground: #14211a;
  --sidebar-border: #d3d9cc;
  --sidebar-accent: #d5ead9;
  --sidebar-accent-foreground: #0b3d24;

  --ov-line: #b1bdac;
  --ov-text: #14211a;
  --ov-muted: #43564b;
  --ov-dim: #66786d;
  --ov-hover: color-mix(in srgb, #0b7f45 8%, transparent);
  --ov-active-bg: color-mix(in srgb, #0b7f45 14%, transparent);
  --mari-accent-text: #08693a;
  --mari-chrome-accent: #0b7f45;
  --tt-gold: #8a5a00;
  --tt-gold-ink: #ffffff;
  --tt-red: #c42b3b;
  --tt-green: #0b7f45;
  --tt-tape: url("theme:tape-light.webp");
  --tt-paper: #fbfaf3;
  --tt-grid: color-mix(in srgb, #0b7f45 12%, transparent);
  --tt-ticket: color-mix(in srgb, #fffef8 95%, transparent);
  --tt-ticket-user: color-mix(in srgb, #fff8e6 95%, transparent);
  --tt-head-bg: #13201a;
  --tt-head-fg: #ffc85a;

  --mari-dialogue-color: #8a4b00;
  --mari-message-time: #4f6458;
  --mari-mode-conversation: #1d5fc9;
  --mari-mode-roleplay: #0b7f45;
  --mari-mode-game: #9a6500;
  --ov-mode-conversation: #1d5fc9;
  --ov-mode-roleplay: #0b7f45;
  --ov-mode-game: #9a6500;
  --mari-home-pink: #c42b3b;
  --mari-home-violet: #6b45c9;

  --mari-app-backdrop: url("theme:floor-day.webp");
  --mari-home-wash: color-mix(in srgb, #fbfaf3 8%, transparent);
  --mari-chat-wash:
    repeating-linear-gradient(90deg, transparent 0 47px, color-mix(in srgb, #0b7f45 11%, transparent) 47px 48px),
    repeating-linear-gradient(0deg, transparent 0 47px, color-mix(in srgb, #0b7f45 11%, transparent) 47px 48px),
    color-mix(in srgb, #f3f1e7 42%, transparent);
  --mari-page-floor: color-mix(in srgb, #f3f1e7 95%, transparent);
  --mari-scrim: color-mix(in srgb, #13201a 45%, transparent);
  --mari-confirm-scrim: color-mix(in srgb, #13201a 18%, transparent);
  --mari-top-bar-plate: color-mix(in srgb, #fbfaf3 94%, transparent);
  --mari-top-bar-plate-active: color-mix(in srgb, #0b7f45 24%, #fbfaf3);
  --mari-home-widget-bg: color-mix(in srgb, #fffef8 97%, transparent);
  --mari-home-widget-border: #b1bdac;
  --mari-home-widget-title-color: #13201a;
  --mari-home-widget-muted: #43564b;
  --mari-stage-empty-bg: linear-gradient(180deg, #eef0e6, #e2e7dc);
  --mari-user-avatar-placeholder: linear-gradient(135deg, #f2b84b, #a8641f);

  --mari-weather-rain-color: #0f7a46;
  --mari-weather-snow-color: #b8860b;
  --mari-weather-fog-color: #b9c4b6;
  --mari-weather-dust-color: #0b7f45;
  --mari-weather-lightning-color: #e0475b;
}

/* phones and portrait tablets get the tall cut of the same room */
@media (orientation: portrait) and (max-width: 900px) {
  :root[data-theme="dark"] {
    --mari-app-backdrop: url("theme:floor-night-phone.webp");
  }
  :root[data-theme="light"] {
    --mari-app-backdrop: url("theme:floor-day-phone.webp");
  }
}

/* ═══════════════════════ FONTS ═══════════════════════ */
body {
  font-family: var(--mari-font-ui);
  font-feature-settings: "tnum" 1;
}

/* ═══════════════════════ TOP BAR: the ticker tape ═══════════════════════
   The tape runs inside the bar's own height: desktop grows the bar by 14px for
   it; phones and tablets keep the normal height and show the tape faintly
   behind the plated tabs (no added row). */
[data-mari-part="top-bar"] {
  --mari-top-bar-bg: var(--background);
  background: var(--sidebar);
  border-bottom: 1px solid var(--ov-line);
  position: relative;
  overflow: clip;
}
[data-mari-part="top-bar"]::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  height: 14px;
  width: calc(100% + 1793px);
  background: var(--tt-tape) 0 0 / 1793px 14px repeat-x;
  pointer-events: none;
}
/* the tape only scrolls on a computer with a mouse: touch devices keep it still for battery */
@media (hover: hover) and (pointer: fine) {
  [data-mari-part="top-bar"]::after {
    animation: tt-tape 90s linear infinite;
    will-change: transform;
  }
}
@keyframes tt-tape {
  to {
    transform: translateX(-1793px);
  }
}
:root[data-overhaul="on"] [data-mari-part="top-bar"]:not([data-split-bar]) {
  height: 58px;
  min-height: 58px;
  padding-bottom: 14px;
  align-items: center;
}
:root[data-overhaul="mobile"] [data-mari-part="top-bar"]::after {
  /* phones and tablets: the tape holds still (battery), faint behind the plated tabs */
  animation: none;
  will-change: auto;
  height: 100%;
  background-size: 1793px 100%;
  opacity: 0.16;
}
.ov-tab,
.ov-icon-btn {
  border-radius: var(--tt-r);
}
.ov-tab__label {
  font-family: var(--tt-mono);
  font-weight: 700;
  font-size: 0.8rem;
  letter-spacing: 0.01em;
}

/* ═══════════════════════ ONE SHAPE EVERYWHERE ═══════════════════════
   Terminal keys: every rounded thing in the app (pills, capsules, round
   avatars, cards, toggles, dots) becomes the same 3px-cornered block, so no
   pill ever sits next to a square. Spinners keep their circle. */
[class*="rounded"]:not(.animate-spin),
.ov-new-pill,
.ov-search,
.ov-seg,
.ov-switch,
.ov-switch > span,
.ov-table-wrap,
.ov-list__empty,
.ov-conn__chip,
.ov-conn__dot,
.ov-conn-defaults,
.ov-card__tokens,
.ov-recent__mode,
.ov-recent__avatar,
.ov-vw__row,
.ov-vw__search,
.ov-thumb,
.ov-gpane__av,
.ov-card,
.ov-card__art,
[data-mari-part="card-art"],
.mari-home-browser-star,
.mari-skip-link,
.ov-sideswitch,
.ov-sideswitch__btn,
.mari-chrome-control,
.mari-chrome-segmented,
.mari-chrome-segmented__button,
input,
select,
textarea,
button {
  border-radius: 3px !important;
}

/* ═══════════════════════ PAGE TITLES ═══════════════════════ */
[data-mari-part="page-title"] {
  font-family: var(--tt-mono);
  font-weight: 800;
  letter-spacing: -0.01em;
}
[data-mari-part="page-title"]::before {
  content: "";
  display: inline-block;
  width: 0.5em;
  height: 0.9em;
  margin-right: 0.4em;
  vertical-align: -0.08em;
  background:
    linear-gradient(var(--tt-green), var(--tt-green)) 50% 0 / 2px 100% no-repeat,
    linear-gradient(var(--tt-green), var(--tt-green)) 50% 55% / 100% 55% no-repeat;
}

/* ═══════════════════════ SIDEBAR: the watchlist ═══════════════════════ */
[data-chat-row] {
  border-radius: var(--tt-r);
  border-bottom: 1px dotted var(--ov-line);
}
[data-chat-row][data-selected="true"] {
  background: color-mix(in srgb, var(--primary) 11%, transparent);
  box-shadow: inset 3px 0 0 var(--primary);
}
.mari-chat-sidebar .mari-chrome-control,
.ov-sidepane input,
.ov-sidepane button {
  border-radius: var(--tt-r);
}

/* ═══════════════════════ PAGES: ledger sheets on chart paper ═══════════════════════ */
[data-mari-part="page"] {
  background:
    repeating-linear-gradient(90deg, transparent 0 31px, var(--tt-grid) 31px 32px),
    repeating-linear-gradient(0deg, transparent 0 31px, var(--tt-grid) 31px 32px),
    var(--tt-paper) !important;
}

/* ═══════════════════════ HOME: a wall of terminal panels ═══════════════════════ */
[data-mari-part="home-widget"] {
  box-shadow: none;
  border-top: 3px solid var(--tt-green) !important;
}
.ov-home-mode {
  background: var(--card) !important;
}
/* Professor Mari rides the rocket across the empty right side of Home's greeting
   (.mari-home-hero is an internal class: shape and picture only) */
.mari-home-hero {
  background: url("theme:mari-rocket.webp") right 24px center / auto 112px no-repeat, var(--mari-home-widget-bg);
  border: 1px solid var(--mari-home-widget-border);
  border-top: 3px solid var(--tt-green);
  border-radius: 3px;
}
@media (max-width: 700px) {
  .mari-home-hero {
    background: var(--mari-home-widget-bg);
  }
}
:root[data-theme="dark"] .mari-home-hero h1 {
  text-shadow: 0 0 2px #050b08, 0 0 14px #050b08;
}
/* empty lists: Mari holding the bags, still smiling */
.ov-list__empty {
  background: url("theme:mari-bags-v13.webp") center 16px / auto 124px no-repeat;
  padding-top: 152px !important;
}
[data-mari-part="home-widget-eyebrow"] {
  display: inline-block;
  align-self: flex-start;
  background: var(--tt-head-bg);
  color: var(--tt-head-fg) !important;
  font-family: var(--tt-mono);
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 2px 6px;
  border-radius: var(--tt-chip-r);
}
[data-mari-part="home-widget-title"] {
  font-family: var(--tt-mono);
  font-weight: 800;
  letter-spacing: -0.01em;
}

/* ═══════════════════════ MESSAGES: order tickets ═══════════════════════ */
[data-mari-part="bubble"] {
  position: relative;
  border-radius: 3px !important;
  border-top: 1px solid var(--ov-line) !important;
  border-right: 1px solid var(--ov-line) !important;
  border-bottom: 1px solid var(--ov-line) !important;
  border-left: 4px solid var(--tt-green) !important;
  background: var(--tt-ticket) !important;
  box-shadow: none !important;
  padding-bottom: 8px;
}
[data-message-role="user"] [data-mari-part="bubble"] {
  border-left-color: var(--tt-gold) !important;
  background: var(--tt-ticket-user) !important;
}
/* the ticket's barcode, bottom right: every slip is a printed confirmation */
[data-mari-part="bubble"]::after {
  content: "";
  position: absolute;
  right: 10px;
  bottom: 5px;
  width: 54px;
  height: 7px;
  background: repeating-linear-gradient(90deg,
      var(--tt-code) 0 1px, transparent 1px 3px, var(--tt-code) 3px 5px, transparent 5px 6px,
      var(--tt-code) 6px 7px, transparent 7px 9px, var(--tt-code) 9px 12px, transparent 12px 13px);
  opacity: 0.55;
  pointer-events: none;
}
[data-message-role="user"] [data-mari-part="bubble"]::after {
  left: 10px;
  right: auto;
}
[data-mari-part="message"] [data-mari-part="header"] {
  font-family: var(--tt-mono);
}
[data-mari-part="message"] [data-mari-part="header"] :is(b, strong, .font-semibold, .font-bold, span):first-child {
  letter-spacing: 0.01em;
}
/* the P&L tag: FILL #n for the character, ORDER #n for you, with the generation time */
[data-mari-part="message"][data-message-role="assistant"] [data-mari-part="time"]::after {
  counter-reset: tt var(--mari-msg-index);
  content: "FILL #" counter(tt);
}
[data-mari-part="message"][data-message-role="user"] [data-mari-part="time"]::after {
  counter-reset: tt var(--mari-msg-index);
  content: "ORDER #" counter(tt);
}
[data-mari-part="message"] [data-mari-part="time"]::after {
  display: inline-block;
  margin-left: 6px;
  padding: 0 5px;
  border-radius: var(--tt-chip-r);
  font-family: var(--tt-mono);
  font-size: 10px;
  font-weight: 700;
  line-height: 15px;
  letter-spacing: 0.04em;
  color: var(--primary-foreground);
  background: var(--tt-green);
}
[data-mari-part="message"][data-message-role="user"] [data-mari-part="time"]::after {
  background: var(--tt-gold);
  color: var(--tt-gold-ink);
}
[data-mari-part="time"] {
  font-family: var(--tt-mono);
  white-space: nowrap;
}
[data-mari-part="avatar"] img,
[data-mari-part="avatar"] button,
[data-mari-part="avatar-placeholder"],
[data-mari-part="mini-avatar"] {
  border-radius: 3px !important;
}
/* a scene break is the ticket's tear line */
[data-mari-part="bubble"] hr {
  border: 0 !important;
  height: 0;
  border-top: 1px dashed color-mix(in srgb, var(--foreground) 40%, transparent) !important;
  margin: 1.1em 0;
}
[data-mari-part="dialogue"] {
  font-weight: var(--mari-dialogue-weight);
}

/* ═══════════════════════ COMPOSER: the order-entry pad ═══════════════════════ */
.mari-chat-input-box {
  border-radius: 3px !important;
  border-right: 1px solid var(--ov-line) !important;
  border-bottom: 1px solid var(--ov-line) !important;
  border-left: 1px solid var(--ov-line) !important;
  border-top: 2px solid var(--tt-green) !important;
  background: var(--tt-ticket) !important;
  box-shadow: none !important;
}
[data-mari-part="composer"] button {
  border-radius: 3px !important;
}
[data-mari-part="composer"] button img {
  border-radius: 3px !important;
}
/* the send key is the BUY key: a solid green block with a rocket */
.mari-chat-send-btn,
[data-mari-part="composer"] button:has(> svg:is(.lucide-send, .lucide-send-horizontal, .lucide-circle-stop, .lucide-stop-circle)) {
  background: var(--tt-green) !important;
  color: var(--primary-foreground) !important;
  opacity: 1;
}
/* dimmed only while it can't send */
.mari-chat-send-btn:disabled,
[data-mari-part="composer"] button:disabled:has(> svg:is(.lucide-send, .lucide-send-horizontal)) {
  opacity: 0.5;
}
:root {
  --mari-icon-send: url("theme:rocket.svg");
}
:root[data-theme="light"] {
  --mari-icon-send: url("theme:rocket-light.svg");
}
[data-mari-part="composer"] textarea {
  font-family: var(--tt-mono);
  font-size: 14px;
}

/* ═══════════════════════ WINDOWS, DRAWERS, DIALOGS: confirmation slips ═══════════════════════ */
.mari-window,
.mari-drawer,
[role="alertdialog"],
.mari-modal-panel,
[role="menu"],
[role="listbox"] {
  border-radius: 3px !important;
  box-shadow: none !important;
}
/* dialogs are confirmation slips: green rule on top and a mono header (barcodes stay on tickets) */
.mari-modal-panel,
[role="alertdialog"] {
  position: relative;
  border-top: 3px solid var(--tt-green) !important;
}
.marinara-chat-popover__title {
  font-family: var(--tt-mono);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
}

/* ═══════════════════════ HOVER (pointer devices only) ═══════════════════════ */
@media (hover: hover) {
  [data-chat-row]:hover {
    background: var(--ov-hover);
  }
}

/* ═══════════════════════ MOTION ═══════════════════════ */
@media (prefers-reduced-motion: reduce) {
  [data-mari-part="top-bar"]::after {
    animation: none;
  }
}
:root[data-marinara-reduced-effects] [data-mari-part="top-bar"]::after {
  animation: none;
}

/* ═══════════════════════ WEATHER-AWARE ART ═══════════════════════ */
/* a storm is a crash: the rain turns red too, and the flash through the glass is a
   deep oxblood (the app's flash strength and timing stay its own; the theme picks the
   colour, and the whole weather layer, flash included, is masked to the window) */
:root[data-mari-weather="storm"] {
  --mari-weather-rain-color: #c25563;
  --mari-weather-lightning-color: #8c1c2b;
}
:root[data-mari-weather="storm"] [data-mari-part="weather"] {
  opacity: 0.78;
}

/* the docked Chat settings window starts under the taller desktop bar, so the tape stays whole */
:root[data-overhaul="on"] .mari-window[data-window="chat-settings"]:not([data-detached="true"]) {
  top: var(--mari-top-bar-height, 58px) !important;
  height: calc(100dvh - var(--mari-top-bar-height, 58px)) !important;
  max-height: calc(100dvh - var(--mari-top-bar-height, 58px)) !important;
}

/* watchlist quotes: the time on each chat row prints like a quote stamp */
[data-chat-row] .tabular-nums {
  font-family: var(--tt-mono);
  font-size: 10.5px;
  letter-spacing: 0.02em;
}

/* the room follows the market weather: rain on the glass, a red crash in a
   storm (the screens go red and the toy rocket falls over), money-snow on the
   rooftops, FUD fog swallowing the skyline */
:root[data-theme="light"][data-mari-weather="rain"],
:root[data-theme="light"][data-mari-weather="hail"] {
  --mari-app-backdrop: url("theme:floor-rain-day.webp");
}
:root[data-theme="dark"][data-mari-weather="rain"],
:root[data-theme="dark"][data-mari-weather="hail"] {
  --mari-app-backdrop: url("theme:floor-rain-night.webp");
}
:root[data-mari-weather="storm"] {
  --mari-app-backdrop: url("theme:floor-storm.webp");
}
:root[data-theme="light"][data-mari-weather="snow"] {
  --mari-app-backdrop: url("theme:floor-snow-day.webp");
}
:root[data-theme="dark"][data-mari-weather="snow"] {
  --mari-app-backdrop: url("theme:floor-snow-night.webp");
}
:root[data-theme="light"][data-mari-weather="fog"],
:root[data-theme="light"][data-mari-weather="cloudy"] {
  --mari-app-backdrop: url("theme:floor-fog-day.webp");
}
:root[data-theme="dark"][data-mari-weather="fog"],
:root[data-theme="dark"][data-mari-weather="cloudy"] {
  --mari-app-backdrop: url("theme:floor-fog-night.webp");
}
/* a storm backdrop is dark by day too: give day text the night wash over it */
:root[data-theme="light"][data-mari-weather="storm"] {
  --mari-chat-wash:
    repeating-linear-gradient(90deg, transparent 0 47px, color-mix(in srgb, #0b7f45 8%, transparent) 47px 48px),
    color-mix(in srgb, #f3f1e7 72%, transparent);
}
@media (orientation: portrait) and (max-width: 900px) {
  :root[data-mari-weather]:not([data-mari-weather="clear"]) {
    --mari-app-backdrop-position: 22% bottom;
  }
}

/* Conversation is the trade blotter: the message list sits on one ruled sheet */
[data-chat-mode="conversation"] .mari-messages-scroll {
  background:
    repeating-linear-gradient(0deg, transparent 0 31px, var(--tt-grid) 31px 32px),
    color-mix(in srgb, var(--tt-paper) 84%, transparent);
  border-left: 1px solid var(--ov-line);
  border-right: 1px solid var(--ov-line);
}

/* Game narration is a terminal panel with the green rule on top */
[data-mari-part="message"][data-game-narration] {
  border-top: 3px solid var(--tt-green) !important;
  box-shadow: none !important;
}
[data-mari-part="game-hud"] {
  box-shadow: none !important;
}

/* Indoors, the weather stays outside the glass: the weather layer is masked to
   the window of the trading den, lined up with the backdrop (cover, centred at
   the bottom, measured from the viewport like the fixed backdrop). Particles
   and bolts only show through the glass, never over the desk, the monitors or
   the wall. A chat's own weather-mask background (inline style) still wins. */
[data-mari-part="weather"] {
  --tt-bw: max(100vw, 177.68vh);
  --tt-bh: max(56.28vw, 100vh);
  -webkit-mask-image: url("theme:wx-window-mask.webp");
  mask-image: url("theme:wx-window-mask.webp");
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-size: var(--tt-bw) var(--tt-bh);
  mask-size: var(--tt-bw) var(--tt-bh);
  -webkit-mask-position: calc((100vw - var(--tt-bw)) * 0.5) calc(100vh - var(--tt-bh) - var(--mari-top-bar-height, 58px));
  mask-position: calc((100vw - var(--tt-bw)) * 0.5) calc(100vh - var(--tt-bh) - var(--mari-top-bar-height, 58px));
}
/* phones and portrait tablets: the weather rooms sit at 22% across, like the backdrop */
@media (orientation: portrait) and (max-width: 900px) {
  [data-mari-part="weather"] {
    -webkit-mask-position: calc((100vw - var(--tt-bw)) * 0.22) calc(100vh - var(--tt-bh) - var(--mari-top-bar-height, 48px));
    mask-position: calc((100vw - var(--tt-bw)) * 0.22) calc(100vh - var(--tt-bh) - var(--mari-top-bar-height, 48px));
  }
  /* clear skies on a phone keep the tall room, so the weather layer uses the same tall glass */
  :root:not([data-mari-weather]) [data-mari-part="weather"],
  :root[data-mari-weather="clear"] [data-mari-part="weather"] {
    -webkit-mask-image: url("theme:wx-window-mask-phone.webp");
    mask-image: url("theme:wx-window-mask-phone.webp");
    --tt-bw: max(100vw, 56.28vh);
    --tt-bh: max(177.68vw, 100vh);
    -webkit-mask-position: calc((100vw - var(--tt-bw)) * 0.5) calc(100vh - var(--tt-bh) - var(--mari-top-bar-height, 48px));
    mask-position: calc((100vw - var(--tt-bw)) * 0.5) calc(100vh - var(--tt-bh) - var(--mari-top-bar-height, 48px));
  }
}
/* in the crash the toy rocket has fallen over, so its spot on the glass is clear */
:root[data-mari-weather="storm"] [data-mari-part="weather"] {
  -webkit-mask-image: url("theme:wx-window-mask-storm.webp");
  mask-image: url("theme:wx-window-mask-storm.webp");
}
/* on a phone or portrait tablet the room is a narrow crop, so the weather keeps to the
   upper glass and stops at the skyline, well clear of the ring light, monitors and desk */
@media (orientation: portrait) and (max-width: 900px) {
  :root[data-mari-weather]:not([data-mari-weather="clear"]) [data-mari-part="weather"] {
    -webkit-mask-image: url("theme:wx-window-mask-upper.webp");
    mask-image: url("theme:wx-window-mask-upper.webp");
  }
}

/* a chat that shows the user's own picked background is not this room: its weather
   behaves as the app does for that picture (no window mask) */
.mari-chat-area:has(> img[data-mari-part="backdrop"][src]:not([src=""]):not([data-default-background])) > [data-mari-part="weather"] {
  -webkit-mask-image: none;
  mask-image: none;
  opacity: 1;
}

/* ═══════════════════════ TAPE: quiet while you work ═══════════════════════
   The tape pauses under the mouse, while the message box has focus and while a
   reply is printing (the send key shows its stop icon then). */
@media (hover: hover) and (pointer: fine) {
  [data-mari-part="top-bar"]:hover::after {
    animation-play-state: paused;
  }
}
:root:has([data-mari-part="composer"]:focus-within) [data-mari-part="top-bar"]::after,
:root:has([data-mari-part="composer"] svg:is(.lucide-circle-stop, .lucide-stop-circle)) [data-mari-part="top-bar"]::after {
  animation-play-state: paused;
}

/* ═══════════════════════ HOME: Recent chats is a watchlist table ═══════════════════════ */
/* the panel fits its rows; the rest of the widget's cell shows the room */
[data-home-widget-id="recent"] > [data-mari-part="home-widget"] {
  height: auto !important;
  align-self: start;
}
[data-home-widget-id="recent"] [data-mari-part="home-widget"] header {
  margin-bottom: 6px;
}
.ov-recent {
  border-top: 1px solid var(--ov-line);
}
.ov-recent > li > button {
  min-height: 32px !important;
  height: 32px;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  border-bottom: 1px dotted var(--ov-line);
}
.ov-recent > li:has(.ov-recent__avatar) > button {
  display: grid !important;
  grid-template-columns: 22px minmax(0, 1fr) 120px 112px;
  align-items: center;
  gap: 12px;
  padding-left: 6px !important;
  padding-right: 6px !important;
}
.ov-recent > li:has(.ov-recent__avatar) > button::after {
  content: "";
  order: 2;
  height: 18px;
  background: url("theme:spark-1.svg") right center / 120px 18px no-repeat;
}
.ov-recent > li:nth-child(6n + 2) > button::after { background-image: url("theme:spark-2.svg"); }
.ov-recent > li:nth-child(6n + 3) > button::after { background-image: url("theme:spark-3.svg"); }
.ov-recent > li:nth-child(6n + 4) > button::after { background-image: url("theme:spark-4.svg"); }
.ov-recent > li:nth-child(6n + 5) > button::after { background-image: url("theme:spark-5.svg"); }
.ov-recent > li:nth-child(6n) > button::after { background-image: url("theme:spark-6.svg"); }
.ov-recent__avatar {
  width: 22px !important;
  height: 22px !important;
  min-width: 22px;
}
.ov-recent__text,
.ov-recent__text strong {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
}
.ov-recent__mode {
  order: 3;
  justify-self: end;
  background: none !important;
  border: 0 !important;
  padding: 0 !important;
  font-family: var(--tt-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.ov-recent > li:last-child > button:not(:has(.ov-recent__avatar)) {
  border-bottom: 0;
  font-family: var(--tt-mono);
  font-size: 13px;
}
@media (hover: hover) {
  .ov-recent > li > button:hover {
    background: var(--ov-hover);
  }
}

/* Home quick actions: five identical keys */
.ov-home-hero-buttons,
.ov-home-modes,
.ov-home-hero-actions {
  gap: 8px !important;
}
.ov-home-hero-buttons button {
  height: 34px !important;
  min-height: 34px !important;
  padding: 0 12px !important;
  gap: 8px !important;
  border: 1px solid var(--ov-line) !important;
  background: var(--card) !important;
  box-shadow: none !important;
  color: var(--foreground) !important;
}
.ov-home-hero-buttons button,
.ov-home-hero-buttons button span {
  font-family: var(--tt-mono) !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  letter-spacing: 0 !important;
}
.ov-home-modes button > span:first-child {
  width: 16px !important;
  height: 16px !important;
  border: 0 !important;
  background: none !important;
}
.ov-home-hero-buttons svg {
  width: 16px !important;
  height: 16px !important;
  color: var(--primary) !important;
}
.ov-home-hero-actions > .ov-btn:not(:has(svg))::before {
  content: "";
  width: 16px;
  height: 16px;
  flex: none;
  background: var(--primary);
  -webkit-mask: url("theme:icon-cap.svg") center / 16px 16px no-repeat;
  mask: url("theme:icon-cap.svg") center / 16px 16px no-repeat;
}
/* the version stays inside the gutter on phones */
.mari-home-hero [class*="tracking-[0.14em]"] {
  letter-spacing: 0.02em !important;
}
.mari-home-hero div:has(> [class*="tracking-[0.14em]"]) {
  align-items: flex-end;
}

/* ═══════════════════════ LEDGER PAGES: a P&L header and ruled columns ═══════════════════════ */
:is(.ov-gallery__head, .ov-settings__head, .ov-vw__top) {
  border-bottom: 2px solid var(--tt-green);
  padding-bottom: 10px;
  background: url("theme:ledger-candles-faint.svg") right 0 bottom 6px / auto 40px repeat-x;
}
.ov-table th {
  background: var(--tt-head-bg) !important;
  color: var(--tt-head-fg) !important;
  font-family: var(--tt-mono);
  font-size: 11.5px;
  letter-spacing: 0.08em;
}
.ov-table td {
  border-top: 1px dotted var(--ov-line);
}
.ov-table td + td:not(.ov-table__more) {
  border-left: 1px solid color-mix(in srgb, var(--tt-green) 30%, transparent);
}
.ov-table td:not(.ov-table__name) {
  font-family: var(--tt-mono);
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
}
.ov-table td.ov-table__num {
  font-weight: 700;
}
/* a lorebook (or anything) without a picture gets a little candle chart */
.ov-thumb:not(:has(img)) {
  background: url("theme:ledger-thumb.svg") center / 80% no-repeat, color-mix(in srgb, var(--tt-gold) 14%, var(--card)) !important;
  border: 1px solid var(--ov-line);
}

/* ═══════════════════════ NO SHADOWS: avatars ═══════════════════════ */
.rpg-avatar-glow::after,
.rpg-avatar-panel::after {
  display: none !important;
}
[data-mari-part="avatar"] button {
  --tw-ring-shadow: 0 0 0 1px var(--ov-line) !important;
  box-shadow: 0 0 0 1px var(--ov-line) !important;
}

/* ═══════════════════════ WATCHLIST: P&L marks and Mari ═══════════════════════ */
/* a quiet mono dot before each time; the open position gets a green triangle */
[data-chat-row] .tabular-nums::before {
  content: "\00B7\00A0";
  color: var(--ov-dim);
}
[data-chat-row][data-selected="true"] .tabular-nums::before {
  content: "\25B2\00A0";
  color: var(--tt-green);
}
/* Mari on her rocket waits at the end of the watchlist (scrolls with it, no row) */
.ov-chats-list {
  background: url("theme:mari-rocket.webp") center bottom 14px / auto 96px no-repeat;
  background-attachment: local;
  padding-bottom: 124px !important;
}
/* Home already has her in the greeting */
:root:has(.mari-home-hero) .ov-chats-list {
  background: none;
  padding-bottom: 4px !important;
}

/* ═══════════════════════ TICKETS: phones merge the name strip into the slip ═══════════════════════ */
[data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="assistant"] [data-mari-part="header"]:not([data-mari-part="bubble"] [data-mari-part="header"]) {
  background: var(--tt-ticket) !important;
  border: 1px solid var(--ov-line);
  border-left: 4px solid var(--tt-green);
  border-bottom: 1px dashed var(--ov-line);
  border-radius: 3px 3px 0 0;
  padding: 3px 8px !important;
  margin-bottom: -2px;
}
[data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="header"][data-placement="outside"] {
  background: var(--tt-ticket-user) !important;
  border: 1px solid var(--ov-line);
  border-left: 4px solid var(--tt-gold);
  border-bottom: 1px dashed var(--ov-line);
  border-radius: 3px 3px 0 0;
  padding: 3px 8px !important;
  margin-bottom: -2px;
}
[data-chat-mode="roleplay"] [data-message-role="user"] .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) {
  align-items: stretch !important;
  width: fit-content;
  max-width: 100%;
  margin-left: auto;
}
[data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="user"]:has([data-mari-part="header"][data-placement="outside"]) [data-mari-part="bubble"],
[data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="assistant"]:has([data-mari-part="header"]:not([data-mari-part="bubble"] [data-mari-part="header"])) [data-mari-part="bubble"] {
  border-top: 0 !important;
  border-top-left-radius: 0 !important;
  border-top-right-radius: 0 !important;
}
/* one-line tickets don't stretch across a wide screen */
:root[data-overhaul="on"] .mari-rp-bubble {
  width: fit-content;
  min-width: min(100%, 28rem);
}
/* narrow screens: the watchlist keeps name and mode, the mini chart steps out */
@media (max-width: 700px) {
  .ov-recent > li:has(.ov-recent__avatar) > button {
    grid-template-columns: 22px minmax(0, 1fr) auto;
  }
  .ov-recent > li:has(.ov-recent__avatar) > button::after {
    display: none;
  }
}
/* dialog icon tiles take the house colour instead of the stock gradient */
.mari-modal-panel [class*="bg-gradient-to-"][class*="from-"] {
  background: var(--tt-green) !important;
  color: var(--primary-foreground) !important;
  box-shadow: none !important;
}

/* Home's greeting, in English only: the trading floor asks a different question.
   The heading keeps its element, text and line box for layout and screen readers;
   its glyphs go transparent and the new line is painted over them. */
:root[lang^="en"] .mari-home-hero h1 {
  position: relative;
  color: transparent !important;
  text-shadow: none !important;
}
:root[lang^="en"] .mari-home-hero h1::after {
  content: "What shall we short tonight?";
  content: "What shall we short tonight?" / "";
  position: absolute;
  inset: 0;
  color: var(--foreground);
  pointer-events: none;
}
:root[lang^="en"][data-theme="light"] .mari-home-hero h1::after {
  content: "What shall we short today?";
  content: "What shall we short today?" / "";
}
:root[lang^="en"][data-theme="dark"] .mari-home-hero h1::after {
  text-shadow: 0 0 2px #050b08, 0 0 14px #050b08;
  /* one letter longer than the app's line: a hair tighter so it fits the same box */
  letter-spacing: -0.055em;
  right: -2px;
}

/* ═══════════════════════ 1.1 — SOLID LEDGER SHEETS ═══════════════════════
   Tables, dense row lists, settings sections, editors and dialogs sit on a
   solid sheet (no alpha, no grid). The chart-paper grid stays in the page
   margins and in the header strips only. */
:root[data-theme="dark"] { --tt-sheet: #0a1611; --tt-card-solid: #0b1712; --tt-side-solid: #08120e; }
:root[data-theme="light"] { --tt-sheet: #fbfaf3; --tt-card-solid: #fffef8; --tt-side-solid: #fbfaf3;
  /* day muted chrome text (editor hints, chat-row times) was ink at 58% alpha = 4.1:1; solid ink-grey is 6.5:1 */
  --mari-chrome-muted: #4a5d53; }
[data-mari-part="page"] { --card: var(--tt-card-solid); }
.ov-table-wrap,
.ov-conn__table,
.ov-org__table,
.ov-sheet__table,
.ov-gpane__table,
.ov-conn-defaults,
.ov-card,
.ov-gallery__tools,
.ov-settings__tabs,
.ov-settings__chips,
.ov-vw__left,
.ov-vw__main,
.ov-settings__scroll,
.ovm-settings__rows,
.ovm-settings__side,
.ovm-settings__main,
.mari-editor-shell {
  background-color: var(--tt-sheet) !important;
  background-image: none !important;
}
/* sidebar chat rows: solid under the rows, the room still shows through the empty sidebar below them */
.ov-chats-rows { background-color: var(--tt-side-solid); }

/* 1.1: on/off switches in table and list rows sit on the row's middle, level with the
   picture beside them (inline-block on the text baseline rode ~3px high). */
:is(td, .ov-lrow, .ov-ltoggle, [class*="row"]) > .ov-switch,
:is(td, .ov-lrow, .ov-ltoggle, [class*="row"]) .ov-switch {
  vertical-align: middle;
}
td:has(> .ov-switch) {
  vertical-align: middle;
}
/* 1.1: the switch column centres its switch between the column rules. */
td.ov-table__lead {
  padding-inline: 0.5rem !important;
  text-align: center !important;
}
td.ov-table__lead > * {
  margin-inline: auto;
}


/* ══ 1.2: the ticker rides with the top bar in fullscreen ══
   In a fullscreen window the top bar slides up out of view and comes back from the top edge.
   The tape is part of the bar (its ::after), but the bar's position: relative (the tape's anchor)
   kept the bar in the page's flow, so the bar slid away and left its 58px row behind, empty.
   Fixed keeps it the tape's anchor too, so bar and tape now leave and come back as one strip,
   over the page, like Velvet Casket's fence. */
:root[data-ov-topbar-autohide] [data-mari-part="top-bar"].is-autohide {
  position: fixed;
}
/* the page starts at the top edge then: the docked Chat settings window and the weather glass
   line up with the top of the window, not with the hidden bar */
:root[data-ov-topbar-autohide] .mari-window[data-window="chat-settings"]:not([data-detached="true"]),
:root[data-ov-topbar-autohide] [data-mari-part="weather"] {
  --mari-top-bar-height: 0px;
}
/* ══ 1.3: a tab group's row takes the ticker ══
   When you're on a grouped tab its tabs get a row of their own under the bar. The tape then runs under
   that row instead of between the two rows of tabs: the bar drops back to a plain 44px and the row gets
   the tape along its foot (the app's tab-row strip), moving and pausing like before. */
:root[data-ov-tabrow][data-overhaul="on"] [data-mari-part="top-bar"]:not([data-split-bar]):not([data-tab-row]) {
  height: 44px;
  min-height: 44px;
  padding-bottom: 0;
}
:root[data-ov-tabrow] [data-mari-part="top-bar"]:not([data-tab-row])::after {
  display: none;
}
[data-tab-row] {
  --mari-tab-row-strip-height: 14px;
  --mari-tab-row-strip-bg: var(--tt-tape) 0 0 / 1793px 14px repeat-x;
}
@media (hover: hover) and (pointer: fine) {
  [data-mari-part="tab-row-strip"] {
    animation: tt-strip 90s linear infinite;
  }
  [data-tab-row]:hover [data-mari-part="tab-row-strip"] {
    animation-play-state: paused;
  }
}
@keyframes tt-strip {
  to {
    background-position: -1793px 0;
  }
}
:root:has([data-mari-part="composer"]:focus-within) [data-mari-part="tab-row-strip"],
:root:has([data-mari-part="composer"] svg:is(.lucide-circle-stop, .lucide-stop-circle)) [data-mari-part="tab-row-strip"] {
  animation-play-state: paused;
}
@media (prefers-reduced-motion: reduce) {
  [data-mari-part="tab-row-strip"] {
    animation: none;
  }
}
:root[data-marinara-reduced-effects] [data-mari-part="tab-row-strip"] {
  animation: none;
}
